WITH scored AS (SELECT id, channel, starts_on, discount_pct, AVG(discount_pct) OVER (PARTITION BY channel ORDER BY discount_pct, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_avg_discount_pct, SUM(discount_pct) OVER (PARTITION BY channel ORDER BY discount_pct, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_sum_discount_pct, COUNT(discount_pct) OVER (PARTITION BY channel ORDER BY discount_pct, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_count_discount_pct, MIN(discount_pct) OVER (PARTITION BY channel ORDER BY discount_pct, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_min_discount_pct FROM promotions) SELECT id, channel, discount_pct, last7_count_discount_pct, last7_min_discount_pct FROM scored ORDER BY id DESC NULLS LAST, channel;
